def transform(grid):
    g=[r[:] for r in grid]
    cells=[(i,j) for i,row in enumerate(g) for j,v in enumerate(row) if v not in (1,2)]
    rmin=min(i for i,j in cells); rmax=max(i for i,j in cells)
    markers=[(i,j) for i,row in enumerate(g) for j,v in enumerate(row) if v==2]
    mr=min(i for i,j in markers); mc=min(j for i,j in markers)
    if mr>rmax: g[rmin-1]=[8]*len(g[0])
    elif mr<rmin: g[rmax+1]=[8]*len(g[0])
    elif mc>max(j for i,j in cells):
        for row in g: row[min(j for i,j in cells)-1]=8
    else:
        for row in g: row[max(j for i,j in cells)+1]=8
    return g

